	if err != nil {
		if ok, invErr := m.IsInvalidDataError(err); ok {
			var templates = make([]localize.TemplatingData, 0)
			if invErr.DataToTemplated != nil {
				for key, val := range invErr.DataToTemplated {
					templates = append(templates, localize.TemplatingData{
						Name:  key,
						Value: val,
					})
				}
			}
			c.JSON(
				http.StatusBadRequest,
				payload.DefaultErrorInvalidDataWithMessage(m.localizer.GetLocalized(userData.Lang, err.Error(), templates...)),
			)
			return
		}
		if m.IsAccessControlError(err) {
			c.JSON(
				http.StatusUnauthorized,
				payload.DefaultErrorInvalidDataWithMessage(m.localizer.GetLocalized(userData.Lang, err.Error())),
			)
			return
		}
		middleware.CaptureError(c, err)
		c.JSON(
			http.StatusInternalServerError,
			payload.DefaultErrorResponseWithMessage(m.localizer.GetLocalized(userData.Lang, "InternalError"), err),
		)
		return
	}
	if res != nil {
		res.Message = m.localizer.GetLocalized(userData.Lang, res.Message)
		c.JSON(http.StatusOK, res)
		return
	}
	c.Status(http.StatusOK)
}

type Enigma struct {
	engine *validator.Validate
	trans  ut.Translator
}

func (v Enigma) BindAndValidate(c *gin.Context, payload any) map[string][]string {
	var err error
	if c.ContentType() == gin.MIMEMultipartPOSTForm {
		err = c.ShouldBind(payload)
	} else {
		err = c.Bind(payload)
	}
	if err != nil {
		var errJSON *json.UnmarshalTypeError
		if errors.As(err, &errJSON) {
			return map[string][]string{
				errJSON.Field: {errJSON.Error()},
			}
		}
		return map[string][]string{"error": {err.Error()}}
	}
	return v.Validate(c, payload)
}

func (v Enigma) queryToFilter(c *gin.Context, payload interface{}, isDive bool) error {
	pVal, pType, vals, err := v.preparingReflection(payload, isDive)
	if err != nil {
		return err
	}

	for i := 0; i < vals.NumField(); i++ {
		tagKeyVal := strings.Split(pType.Elem().Field(i).Tag.Get("bindQuery"), ";")
		var tags = map[string]string{}
		for j := 0; j < len(tagKeyVal); j++ {
			if tagKeyVal[j] == "" {
				continue
			}
			keyVals := strings.Split(tagKeyVal[j], "=")
			if len(keyVals) >= 2 {
				tags[keyVals[0]] = keyVals[1]
			}
		}

		if _, ok := tags["ignore"]; ok {
			continue
		}

		reqField := pType.Elem().Field(i).Tag.Get("json")
		if rn, ok := tags["reqName"]; ok {
			reqField = rn
		}

		reqVal := getFromRequest(c, tags["reqPlace"], reqField)
		if binder, ok := bindingRules[tags["dataType"]]; ok {
			finalVal, err := binder(c, reqVal, tags)
			if err != nil {
				return err
			}
			vals.Field(i).Set(reflect.ValueOf(finalVal))
			continue
		}
		vals.Field(i).Set(reflect.ValueOf(reqVal))
	}
	return nil
}

type Clock interface {
	ParseWithTzFromCtx(ctx context.Context, value string, format string) time.Time
	Now(ctx context.Context) time.Time
	NowUnix() int64
	GetTimeZoneByName(name string) *time.Location
	SetTimezoneToContext(ctx context.Context, val string) context.Context
	GetTimezoneFromContext(ctx context.Context) *time.Location
}

func (t clock) Now(ctx context.Context) time.Time {
	lz := t.GetTimezoneFromContext(ctx)
	return time.Now().In(lz)
}

func (t clock) GetTimezoneFromContext(ctx context.Context) *time.Location {
	lz := time.UTC
	if ct, ok := ctx.Value(CtxKeyTimezone).(time.Location); ok {
		lz = &ct
	}
	return lz
}

func (m Mapper) SortingByStructField(vals interface{}, fieldName string, sorting SortingDirection) interface{} {
	pVal := reflect.ValueOf(vals)
	if !m.typeIsArray(vals) {
		return vals
	}

	var newArr = make([]interface{}, pVal.Len())
	for i := 0; i < pVal.Len(); i++ {
		newArr[i] = pVal.Index(i).Interface()
	}

	for i := 0; i < len(newArr)-1; i++ {
		currentVal := pVal.Index(i).FieldByName(fieldName)
		kind := currentVal.Kind()
		if currentVal.Kind() == reflect.Struct {
			pType := reflect.TypeOf(currentVal.Interface())
			if pType.Name() == "Time" {
				kind = KindIsTime
			}
		}
		fn := sortingFunc[sorting][kind]
		prev, next := fn(reflect.ValueOf(newArr[i]), reflect.ValueOf(newArr[i+1]), fieldName)
		newArr[i] = prev
		newArr[i+1] = next
	}
	return newArr
}

// DefaultLogger initializes Zerolog with dynamic level and caller frame skipping
func DefaultLogger() ReZero {
	logLevel := strings.ToLower(os.Getenv("LOG_LEVEL"))
	level := zerolog.InfoLevel
	switch logLevel {
	case "debug":
		level = zerolog.DebugLevel
	case "info":
		level = zerolog.InfoLevel
	case "warn":
		level = zerolog.WarnLevel
	case "error":
		level = zerolog.ErrorLevel
	}

	zerolog.CallerSkipFrameCount = 4
	zerolog.CallerMarshalFunc = func(pc uintptr, file string, line int) string {
		short := file
		for i := len(file) - 1; i > 0; i-- {
			if file[i] == '/' {
				short = file[i+1:]
				break
			}
		}
		return fmt.Sprintf("%s:%d", short, line)
	}

	output := zerolog.ConsoleWriter{Out: os.Stdout, TimeFormat: time.RFC3339}
	logger := zerolog.New(output).With().Timestamp().Caller().Logger()
	Log = &logger
	return ReZero{logger: &logger, level: level}
}

// SentryMiddleware enriches Sentry events with request details and sanitized headers
func SentryMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		hub := sentry.GetHubFromContext(c.Request.Context())
		if hub == nil {
			hub = sentry.CurrentHub().Clone()
		}
		ctx := sentry.SetHubOnContext(c.Request.Context(), hub)
		c.Request = c.Request.WithContext(ctx)

		hub.ConfigureScope(func(scope *sentry.Scope) {
			scope.SetRequest(c.Request)
			scope.SetTag("request.path", c.Request.URL.Path)
			scope.SetTag("request.method", c.Request.Method)
			scope.SetTag("request.remote_addr", c.ClientIP())
			scope.SetExtra("request.headers", convertHeaders(c.Request.Header))
		})

		c.Next()
		enrichSentryWithUserData(hub, c)
	}
}

func convertHeaders(headers http.Header) map[string]string {
	result := make(map[string]string)
	for key, values := range headers {
		if len(values) > 0 {
			if key == "Authorization" || key == "Cookie" || key == "X-Api-Key" {
				result[key] = "[Filtered]"
			} else {
				result[key] = values[0]
			}
		}
	}
	return result
}
